CREATE TRIGGER RefFacilityLocalCode_Combined
	ON RefFacilityLocalCode
	FOR INSERT, UPDATE, DELETE
	AS
	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT RFT_PK, 'RFT' FROM inserted
	JOIN RefFacility ON RFT_Code = RFL_RFT_NKFacilityCode
	UNION
	SELECT RFT_PK, 'RFT' FROM deleted
	JOIN RefFacility ON RFT_Code = RFL_RFT_NKFacilityCode

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

CREATE TRIGGER RefFacilityLocalCode_DataProcessingResult_Delete
	ON RefFacilityLocalCode
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.RFL_PK
	END
GO
